const D = { density:.5, energy:.6, speed:1, scale:1, hue:200, x:.5, y:.5, style:'mono', flow:.6, act:'weave', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2, HP=Math.PI/2, PIc=Math.PI;
const md=(a,n)=>((a%n)+n)%n;
const ez=t=>{t=clp(t,0,1);return t*t*(3-2*t);};
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const style=P.style;
const mono=style==='mono', ribbon=style==='ribbon', neon=style==='neon', blue=style==='blueprint';
const en=clp(P.energy,0,1)*(.55+.6*K.intensity);
const dens=clp(P.density,0,1);
const hue=md(P.hue,360);

// tile size from density (density is the FIRST poke param — structural)
const ts=Math.max(u*0.045, u*(0.17-dens*0.125));
const cols=Math.ceil(W/ts)+1, rows=Math.ceil(Hh/ts)+1;

// palette per style discipline
let bgH,bgS,bgB, lnH,lnS,lnB, ln2H;
if(mono){ bgH=hue; bgS=22; bgB=9; lnH=hue; lnS=8; lnB=92; ln2H=hue; }
else if(ribbon){ bgH=md(hue+30,360); bgS=16; bgB=90; lnH=hue; lnS=68; lnB=82; ln2H=md(hue+168,360); }
else if(neon){ bgH=hue; bgS=62; bgB=6; lnH=hue; lnS=92; lnB=100; ln2H=md(hue+140,360); }
else { bgH=md(hue+5,360); bgS=68; bgB=26; lnH=45; lnS=5; lnB=98; ln2H=45; }

function arcs0(px,py,tsz,par){
  // draw the two Smith-truchet quarter arcs for a tile using GLOBAL funcs
  if(par===0){ arc(px,py,tsz,tsz,0,HP); arc(px+tsz,py+tsz,tsz,tsz,PIc,PIc+HP); }
  else { arc(px+tsz,py,tsz,tsz,HP,PIc); arc(px,py+tsz,tsz,tsz,-HP,0); }
}

// ---- cached base field (keyed on size/seed/style/density bucket) ----
const dB=Math.round(dens*5);
const key=W+'x'+Hh+'|'+P.seed+'|'+style+'|'+dB;
if(S.key!==key){
  S.key=key;
  const g=createGraphics(W,Hh); g.colorMode(g.HSB,360,100,100,100); g.clear();
  g.noFill(); g.strokeCap(g.ROUND);
  const sw=ts*(mono?0.06:ribbon?0.30:neon?0.13:0.05)*clp(P.scale,.5,2);
  for(let cy=0;cy<rows;cy++){
    for(let cx=0;cx<cols;cx++){
      const px=cx*ts, py=cy*ts;
      const par = fr(cx*13.7+cy*91.3+3.1)>0.5?1:0;
      const sh = 0.82+0.32*fr(cx*3.1+cy*7.9);
      g.strokeWeight(sw);
      if(ribbon){ g.stroke((par?ln2H:lnH), lnS, clp(lnB*sh,0,100), 100); }
      else if(blue){ g.stroke(lnH,lnS,lnB,88); }
      else { g.stroke(lnH, mono?10:lnS, clp(lnB*(mono?sh:1),0,100), neon?55:100); }
      if(par===0){ g.arc(px,py,ts,ts,0,HP); g.arc(px+ts,py+ts,ts,ts,PIc,PIc+HP); }
      else { g.arc(px+ts,py,ts,ts,HP,PIc); g.arc(px,py+ts,ts,ts,-HP,0); }
    }
  }
  if(blue){ g.stroke(45,5,98,18); g.strokeWeight(0.6);
    for(let x=0;x<=W;x+=ts){g.line(x,0,x,Hh);} for(let y=0;y<=Hh;y+=ts){g.line(0,y,W,y);} }
  S.base=g; S.ts=ts; S.sw=sw;
  const nAnim=Math.min(64, Math.round(10+dens*44));
  const list=[];
  for(let i=0;i<nAnim;i++){
    const cx=Math.floor(fr(i*4.7+1)*cols), cy=Math.floor(fr(i*8.3+2)*rows);
    list.push({cx,cy, par: fr(cx*13.7+cy*91.3+3.1)>0.5?1:0, sp:fr(i*5.1+7), rate:0.13+0.24*fr(i*2.3+4)});
  }
  S.anim=list; S.flowAng=TAU*fr(99.3);
}
const ts2=S.ts, sw=S.sw;

// ---- LIVE COMPOSITE ----
noStroke();
background(bgH,bgS,bgB);
image(S.base,0,0);

// spinning tiles — cover cell, redraw orientation-0 arcs rotated (90deg = orientation flip)
strokeCap(ROUND); noFill();
const flipRate=P.speed;
const popMass = P.act==='pulse'? (0.4+0.9*K.pulse) : 1;
const activeFrac = clp((0.35+0.65*en)*popMass,0,1);
const list=S.anim;
for(let i=0;i<list.length;i++){
  if(i/list.length > activeFrac) continue;
  const a=list[i];
  const px=a.cx*ts2, py=a.cy*ts2, cxp=px+ts2/2, cyp=py+ts2/2;
  noStroke(); fill(bgH,bgS,bgB); rect(px-1,py-1,ts2+2,ts2+2);
  const gg=K.beat*a.rate*flipRate + a.sp + K.t*0.02;
  const steps=Math.floor(gg), frc=gg-steps, ang=(a.par+steps+ez(frc))*HP;
  push(); translate(cxp,cyp); rotate(ang); noFill();
  const cH = neon?hue : (ribbon?(a.par?ln2H:lnH):lnH);
  const cB = 100;
  if(neon){
    stroke(cH,90,100,26); strokeWeight(sw*2.4); arc(-ts2/2,-ts2/2,ts2,ts2,0,HP); arc(ts2/2,ts2/2,ts2,ts2,PIc,PIc+HP);
    stroke(cH,70,100,100); strokeWeight(sw); arc(-ts2/2,-ts2/2,ts2,ts2,0,HP); arc(ts2/2,ts2/2,ts2,ts2,PIc,PIc+HP);
  } else {
    stroke(cH, mono?12:lnS, cB, blue?92:100); strokeWeight(sw); arc(-ts2/2,-ts2/2,ts2,ts2,0,HP); arc(ts2/2,ts2/2,ts2,ts2,PIc,PIc+HP);
  }
  pop();
}

// ---- connected-path flow: traveling glow blobs (ADD, K.t continuous — real-time motion floor) ----
blendMode(ADD);
const flow=clp(P.flow,0,1);
const nblob=2+Math.round(flow*2);
const drift = P.act==='drift'? K.t*0.05 : 0;
for(let i=0;i<nblob;i++){
  const s1=0.028+0.017*i;
  const bx=W*(0.5+0.42*Math.sin(K.t*s1*P.speed*TAU*0.5 + i*2.1 + drift));
  const by=Hh*(0.5+0.42*Math.cos(K.t*s1*P.speed*TAU*0.4 + i*1.7 + drift*0.7));
  const rr=u*(0.16+0.06*Math.sin(K.t*0.5+i))*(0.7+0.7*en)*(1+0.4*K.pulse+0.5*A.bass);
  const hb=md(hue + (neon?150:44) + i*26 + K.t*4.5, 360);
  for(let k=3;k>=1;k--){ noStroke(); fill(hb, mono?55:60, 100, (mono?9:13)*(0.5+0.8*en)*k/3); circle(bx,by, rr*k*0.62); }
}
// treble sparkle along the field
if(A.treble>0.04){ const ns=Math.floor(18*A.treble); for(let i=0;i<ns;i++){ const gx=fr(i*1.7+Math.floor(K.beat*4))*W, gy=fr(i*2.3+7+Math.floor(K.beat*4))*Hh; fill(md(hue+80,360),40,100,40*A.treble); circle(gx,gy,u*0.006); } }

blendMode(BLEND); drawingContext.shadowBlur=0;
